"""On-disk persistence for expenses.

The store is a single JSON file: {"schema_version": N, "expenses": [ ... ]}.

Each expense record looks like:
    {
      "id": 1,
      "date": "2024-03-04",
      "amount_usd": 42.31,          # normalized to USD at write time
      "original_amount": 39.0,      # what the user actually typed
      "original_currency": "EUR",
      "category": "food",
      "note": "groceries"
    }
"""

import json
import os
from typing import Dict, List, Optional

from tally.config import SCHEMA_VERSION
from tally.rates import normalize


def empty_store():
    return {"schema_version": SCHEMA_VERSION, "expenses": []}


def migrate(data):
    """Bring an older on-disk store up to the current schema version.

    v1 records stored a single "amount" field already in USD and a "currency"
    field naming the original currency. v2 splits that into amount_usd plus the
    original amount/currency pair.
    """
    version = data.get("schema_version", 1)
    if version == 1:
        for exp in data.get("expenses", []):
            if "amount_usd" not in exp and "amount" in exp:
                exp["amount_usd"] = exp.pop("amount")
            exp.setdefault("original_amount", exp.get("amount_usd"))
            exp.setdefault("original_currency", exp.pop("currency", "USD"))
        version = 2
    data["schema_version"] = SCHEMA_VERSION
    return data


def load(path):
    """Load the store at `path`, or return an empty store if it does not exist."""
    if not os.path.exists(path):
        return empty_store()
    with open(path, "r") as fh:
        data = json.load(fh)
    return migrate(data)


def save(path, data):
    """Write the store to `path` (pretty-printed, stable key order)."""
    directory = os.path.dirname(path)
    if directory and not os.path.isdir(directory):
        os.makedirs(directory)
    with open(path, "w") as fh:
        json.dump(data, fh, indent=2, sort_keys=True)
        fh.write("\n")


def next_id(data):
    ids = [exp.get("id", 0) for exp in data["expenses"]]
    if not ids:
        return 1
    return max(ids) + 1


def add_expense(data, date, amount, currency, category, note=""):
    """Append a new expense and return the created record.

    `amount`/`currency` are what the user supplied; the amount is normalized to
    USD before it is stored. `data` is mutated in place.
    """
    amount_usd = normalize(amount, currency)
    record = {
        "id": next_id(data),
        "date": date,
        "amount_usd": amount_usd,
        "original_amount": amount,
        "original_currency": currency.upper(),
        "category": category,
        "note": note,
    }
    data["expenses"].append(record)
    return record


def find_expense(data, expense_id):
    for exp in data["expenses"]:
        if exp.get("id") == expense_id:
            return exp
    return None


def all_expenses(data):
    return list(data["expenses"])

"""Currency conversion.

Every amount that enters the store is normalized to USD (see docs/requirements.md).
`RATES` maps a currency code to the number of USD one unit is worth. The rates are
treated as fixed constants: several tests pin totals computed from them.
"""

from tally.config import DEFAULT_CURRENCY

# 1 unit of <currency> is worth RATES[<currency>] USD.
RATES = {
    "USD": 1.0,
    "EUR": 1.08,
    "GBP": 1.27,
    "SGD": 0.74,
    "JPY": 0.0067,
    "INR": 0.012,
}


def supported_currencies():
    """Return the sorted list of currency codes we can convert."""
    return sorted(RATES.keys())


def to_usd(amount, currency):
    """Convert `amount` given in `currency` to USD.

    The currency code is matched case-insensitively. Unknown codes raise
    ValueError so a typo never silently produces a wrong number.
    """
    code = currency.upper()
    if code not in RATES:
        raise ValueError(
            "unsupported currency {!r}; known: {}".format(
                currency, ", ".join(supported_currencies())
            )
        )
    return round(amount * RATES[code], 2)


def normalize(amount, currency):
    """Normalize an amount in `currency` into USD, the stored representation."""
    return to_usd(amount, currency)


def is_default_currency(currency):
    return currency.upper() == DEFAULT_CURRENCY

"""Small helpers: date parsing and money rounding."""

import datetime
from typing import Union

Dateish = Union[str, datetime.date]


def parse_date(text):
    """Parse a date written as YYYY-MM-DD or YYYY-MM.

    A bare YYYY-MM is treated as the first day of that month. Raises ValueError
    on anything else.
    """
    text = text.strip()
    for fmt in ("%Y-%m-%d", "%Y-%m"):
        try:
            return datetime.datetime.strptime(text, fmt).date()
        except ValueError:
            continue
    raise ValueError("unrecognized date {!r}; use YYYY-MM-DD or YYYY-MM".format(text))


def month_key(d):
    """Return the YYYY-MM string for a date."""
    if isinstance(d, str):
        d = parse_date(d)
    return "{:04d}-{:02d}".format(d.year, d.month)


def round_money(amount):
    """Round a money amount to 2 decimal places, rounding halves up.

    Python's built-in round() rounds halves to even, which surprises people who
    expect 2.675 -> 2.68. The small nudge below makes the behaviour half-up so
    reported totals match what a hand calculator would show.
    """
    return round(amount + 1e-9, 2)

